"""棋牌三合一 v1.10.0 —— 两文件构建版，完整源码都在此文件中。

上传方式：
  1. build.yml -> .github/workflows/build.yml
  2. 本文件 build_project.py -> 仓库根目录
保留原仓库的「棋牌三合一.png」可沿用原图标；缺少时使用内置矢量图标。

本地：python3 build_project.py --output generated-app
随后在 generated-app 运行 bash scripts/test_ai.sh 和 ./gradlew :app:assembleDebug。
需要 Python 3.10 及以上、JDK 17、Android SDK 34。仅使用 Python 标准库。
修改源码请编辑下方对应的 FILES 段；内部工程只在构建时生成，无需逐个上传。
"""

